SOURCE_INPUTS={'roaster': {'sha256': '959a24c5e06ea175af65277918e98d247655fec2011ab55673c0e666ffb02c9a', 'compressed': ''}, 'table': {'sha256': 'b4880f9c24dda10b566fa215c394295b6522a8ad448486918c591826480c09d8', 'compressed': ''}, 'grinder': {'sha256': '1549710195f7d03df8536b1e7c35f0637099e65e0acf7367c0dd8f65e9d08b44', 'compressed': ''}}
